def _recip_tile(x_ptr, n_elem, first_block, pid, BLOCK: tl.constexpr):
    offs = (pid - first_block) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elem
    x = tl.load(x_ptr + offs, mask=mask, other=1.0)
    tl.store(x_ptr + offs, _reciprocal(x).to(x.dtype), mask=mask)


