@triton.jit
def _recip_strided_kernel(
    x_ptr,
    n_elem,
    N0,
    S0,
    N1,
    S1,
    N2,
    S2,
    N3,
    S3,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
