def _launch_fused(slots):
    """slots: list of (tensor, numel) with 1.._MAX_SLOTS same-dtype entries."""
    ptrs = [s[0] for s in slots]
    nums = [s[1] for s in slots]
    live = len(slots)
    if nums.count(nums[0]) == live:
        # Equal element counts: numel and tiles-per-tensor become constexprs, so
        # the launch carries pointers only.
        n = nums[0]
        tpb = _n_blocks(n)
        if live < _MAX_SLOTS:
            ptrs += [ptrs[0]] * (_MAX_SLOTS - live)
        _recip_fused_eq_kernel[(live * tpb,)](*ptrs, n, tpb, _BLOCK)
        return
    if live < _MAX_SLOTS:
        ptrs += [ptrs[0]] * (_MAX_SLOTS - live)
        nums += [0] * (_MAX_SLOTS - live)
    total = _n_blocks(nums[0])
    for i in range(1, _MAX_SLOTS):
        total += _n_blocks(nums[i])
    _recip_fused_kernel[(total,)](*ptrs, *nums, _BLOCK)


def _launch_strided(t, n, dims):
    padded = list(dims) + [(1, 0)] * (_MAX_RANK - len(dims))
    args = []
    for sz, st in padded:
        args.append(sz)
        args.append(st)
    _recip_strided_kernel[(_n_blocks(n),)](t, n, *args, len(dims), _BLOCK)


def _launch(t):
    if t.numel() == 0:
        return
    dims = _collapse(t.shape, t.stride())
    rank = len(dims)
    if rank == 0:
        _launch_flat(t, 1)
    elif rank == 1 and dims[0][1] == 1:
        _launch_flat(t, dims[0][0])
    elif rank <= _MAX_RANK:
        _launch_strided(t, t.numel(), dims)
    else:
        # Extremely high-rank gappy view: recurse over zero-copy sub-views.
        for i in range(t.shape[0]):
            _launch(t[i])


def _flat_numel(t):
    """numel if the tensor's storage span is exactly its element set, else None."""
    n = t.numel()
    if n == 0:
        return 0
    dims = _collapse(t.shape, t.stride())
    rank = len(dims)
    if rank == 0:
        return 1
    if rank == 1 and dims[0][1] == 1:
        return dims[0][0]
    return None


def _reject(dtype):
    raise RuntimeError(
        "result type Float can't be cast to the desired output type "
        f"{str(dtype).replace('torch.', '').capitalize()}"
    )


def foreach_reciprocal_(self):
    if not isinstance(self, (list, tuple)):
        if isinstance(self, torch.Tensor):
            raise TypeError(
                "argument 'self' (position 1) must be tuple of Tensors, " "not Tensor"
            )
        raise TypeError("argument 'self' must be tuple of Tensors")
    n_entries = len(self)
    if n_entries == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        if t.dtype not in _FLOAT_DTYPES:
            _reject(t.dtype)

    if n_entries == 1:
        t = self[0]
        if t.is_contiguous():
            n = t.numel()
            if n:
                _launch_flat(t, n)
        else:
            _launch(t)
        return None

    # Collect one (start, end, tensor, numel) span per entry. The contiguous
    # case -- every streaming entry -- answers from C-level metadata and skips
    # the stride-collapsing walk, which is the dominant per-call Python cost for
    # a 16-entry list.
    slots = []
    fusable = True
    for t in self:
        if t.is_contiguous():
            n = t.numel()
        else:
            n = _flat_numel(t)
            if n is None:
                fusable = False
                break
        if n:
            ptr = t.data_ptr()
            slots.append((ptr, ptr + n * t.element_size(), t, n))
    if fusable:
        slots = sorted(slots)
        for i in range(len(slots) - 1):
            if slots[i][1] > slots[i + 1][0]:
                fusable = False
                break
    if not fusable:
        for t in self:
            _launch(t)
        return None

    # Group by dtype (a Triton pointer argument fixes its element type). A small
    # group whose device work cannot hide a launch becomes ONE fused launch;
    # larger entries keep one launch each, which pipelines better.
    groups = {}
    for _, _, t, n in slots:
        bucket = groups.get(t.dtype)
        if bucket is None:
            groups[t.dtype] = [(t, n)]
        else:
            bucket.append((t, n))
    for chunk in groups.values():
        for i in range(0, len(chunk), _MAX_SLOTS):
            part = chunk[i : i + _MAX_SLOTS]
            if max(n for _, n in part) > _FUSE_MAX_NUMEL:
                for t, n in part:
                    _launch_flat(t, n)
            else:
                _launch_fused(part)
    return None
